// THROWAWAY Sky study. Rendering only: no client astronomy or cloud reconstruction.
import {cssVars} from './sky-tokens.js';
const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const q=new URLSearchParams(location.search),names={A:'Horizon instrument',B:'Night planner',C:'Evidence ledger'};
const times=['2026-09-04T00:00:00Z','2026-09-04T01:00:00Z','2026-09-04T06:00:00Z','2026-09-04T12:00:00Z','2026-09-05T00:00:00Z'];
const state={variant:names[q.get('variant')]?q.get('variant'):'A',theme:['light','dark','night'].includes(q.get('theme'))?q.get('theme'):'light',focus:q.get('focus')==='point'?'point':'site',instant:times.includes(q.get('instant'))?q.get('instant'):times[0],mode:'capture',cv:'normal',selection:null};
let inspectorOpener=null;
let T,capture,registry,live={},pending=false,sequence=0;const records=new Map();
try{[T,capture,registry]=await Promise.all(['tokens.json','sky-captures.json','sky-registry.json'].map(async p=>{const r=await fetch(p);if(!r.ok)throw Error(p+': '+r.status);return r.json()}))}catch(e){$('#notice').textContent='Required prototype assets unavailable: '+e.message;throw e}
const font=document.createElement('link');font.rel='stylesheet';font.href='https://fonts.googleapis.com/css2?'+T.variants.C.fonts.google+'&display=swap';document.head.append(font);
const position=()=>state.focus==='site'?{latitude:registry.site.record.position.latitude,longitude:registry.site.record.position.longitude}:{latitude:47.5615,longitude:-52.7126};
const glyph=(cls='unrecognised')=>`<svg class="glyph" role="img" aria-label="${esc(cls.replaceAll('_',' '))}" style="color:var(--cls-${cls},var(--muted))"><use href="#g-${esc(cls)}"/></svg>`;
const stamp=t=>t?String(t).slice(5,16).replace('T',' ')+'Z':'Not supplied';
const number=(v,unit='')=>typeof v==='number'&&Number.isFinite(v)?`${Number(v.toFixed(2))}${unit?' '+unit:''}`:'—';
const store=(key,obj)=>{records.set(key,obj);return esc(key)};
function response(route){
 if(state.mode==='outage')return {response:{data_mode:'unavailable',notices:['Deliberately unavailable UI state; no numeric fixture or fallback.']},request_url:'UI state study',captured_at:null};
 if(state.mode==='live')return live[route]??{response:{data_mode:'unavailable',notices:[pending?'Request pending':'Live response not available']}};
 return capture.requests.find(r=>{const u=new URL(r.request_url);return u.pathname.endsWith('/'+route)&&(route==='space-weather'||route==='timeline'||(Number(u.searchParams.get('latitude'))===position().latitude&&u.searchParams.get('valid_time')===state.instant))})??{response:{data_mode:'unavailable',notices:['No captured request at this Focus']}};
}
const astro=()=>response('astronomy').response??{};
const point=()=>response('point').response??{};
const space=()=>response('space-weather').response??{};
const validAstro=()=>astro().data_mode==='live'&&!!astro().provenance;
function entry(key,label,value,unit,source,cls,detail,raw,request){return {key,label,value,unit,source,cls,detail,raw,request}}
function astroEntry(key,label,unit='°'){
 const a=astro(),v=key==='moon_illumination'?(a.moon?.illuminated_fraction==null?null:a.moon.illuminated_fraction*100):key==='moon_phase'?a.moon?.phase_deg:a[key];
 return entry('astro:'+key,label,validAstro()?v:null,unit,a.provenance?.source_id??'Astronomy',validAstro()?'derived_here':'absent',validAstro()?(key.startsWith('moon_')&&!key.endsWith('altitude_deg')?'Computed here · geometric lunar quantity':'Computed here · geometric altitude; site horizon not applied'):(a.notices??['Astronomy unavailable']).join(' · '),{value:validAstro()?v:null,provenance:a.provenance,notices:a.notices,valid_time:a.valid_time,classification_note:'derived-here mapping follows the explicit astronomy derivation contract; the endpoint omits evidence_class.'},response('astronomy'));
}
function fieldEntry(key,label){
 const fs=(point().fields??[]).filter(f=>f.field===key);const f=fs.find(f=>f.provenance?.source_id==='noaa-gfs')??fs[0],p=f?.provenance;
 return entry('field:'+key,label,f?.value??null,p?.normalized_units??'',p?.source_id??'No field returned',p?.evidence_class??'absent',f?.value==null?(f?.blocked?.reason??f?.absence_state??'No matching field returned at this Focus'):`Retrieval ${p?.freshness?.status??'unknown'} · run ${p?.run_stale==null?'age unknown':p.run_stale?'stale':'current'}`,f??{field:key,value:null,reason:'Not returned by /point at this Focus',notices:point().notices},response('point'));
}
function row(e){store(e.key,e);return `<button class="row" data-inspect="${esc(e.key)}">${glyph(e.cls)}<span>${esc(e.label)}<small>${esc(e.source)} · ${esc(e.detail)}</small></span><span class="value">${esc(number(e.value,e.unit))} <span aria-hidden="true">↗</span></span></button>`}
function absence(key,label,reason,source='Not served') {return entry('missing:'+key,label,null,'',source,'absent',reason,{value:null,reason},null)}
const header=(title,meta='')=>`<div class="panelhead"><h2>${title}</h2><small>${meta}</small></div>`;
function geometry(){return `<section class="panel">${header('Geometry at the instant','◆ Derived here · DE442')}${[astroEntry('sun_altitude_deg','Sun altitude'),astroEntry('moon_altitude_deg','Moon altitude'),astroEntry('core_altitude_deg','Galactic core altitude'),astroEntry('moon_illumination','Moon illuminated','%'),astroEntry('moon_phase','Moon phase angle')].map(row).join('')}<p class="hint">Altitudes use the API’s geometric reference. Azimuths are absent, so no Sun, Moon or core marker is placed against the site horizon.</p></section>`}
function horizon(){
 const site=state.focus==='site',r=registry.site.record;store('horizon',entry('horizon','Registered horizon',null,'',site?'Site registry':'No site',site?'unrecognised':'absent',site?r.note:'Arbitrary points do not borrow a nearby site horizon.',site?registry.site:{value:null,reason:'no_site'},null));
 const rings=[0,30,60].map(a=>`<circle class="dome-grid" cx="240" cy="175" r="${145*(90-a)/90}"/><text x="246" y="${175-145*(90-a)/90+14}">${a}°</text>`).join('');
 const pts=site?r.horizon.elevation_deg.map((alt,i)=>{const t=i*10*Math.PI/180,rad=145*(90-alt)/90;return `${240+rad*Math.sin(t)},${175-rad*Math.cos(t)}`}).join(' '):'';
 return `<section class="panel">${header('Horizon / looking up',site?'Registered · not field surveyed':'No registered horizon')}<svg class="dome" viewBox="0 0 480 350" role="img" aria-label="${site?'Signal Hill registered horizon, hand-read from maps and not surveyed':'Empty reference grid; no site horizon'}; no directional cloud or celestial positions inferred"><title>Sky reference grid; clockwise bearings from true north</title>${rings}<path class="dome-grid" d="M95 175H385M240 30V320"/>${site?`<polygon class="horizon-line" points="${pts}"/>`:''}<text x="240" y="20" text-anchor="middle">N · 000°</text><text x="407" y="180">E</text><text x="240" y="344" text-anchor="middle">S · 180°</text><text x="62" y="180">W</text><rect x="117" y="137" width="246" height="80" fill="var(--panel)"/><text class="big" x="240" y="167" text-anchor="middle">${site?'Registered horizon only':'Horizon unknown'}</text><text x="240" y="191" text-anchor="middle">Directional sky evidence absent</text><text x="240" y="208" text-anchor="middle">Zenith at centre · not a cloud map</text></svg><button data-inspect="horizon">${glyph(site?'unrecognised':'absent')} ${site?'Inspect site registry':'Why no horizon?'}</button><p class="hint">${site?'Dashed trace: hand-registered every 10° from map reading; about 1° precision, terrain check not run. Negative horizon dips extend outside the 0° reference circle.':'This arbitrary point has no registered horizon. Signal Hill’s outline is not reused.'}</p></section>`;
}
function clouds(){
 const ee=[['cloud_low','Low'],['cloud_middle','Middle'],['cloud_high','High']].map(([k,n])=>fieldEntry(k,n+' cloud'));
 return `<section class="panel">${header('Cloud layers','GFS · point fractions')}<div class="clouds">${ee.map(e=>{store(e.key,e);const v=typeof e.value==='number'?e.value:null;return `<button class="cloud-dial" data-inspect="${esc(e.key)}"><span>${esc(e.label)}</span><svg viewBox="0 0 100 100" role="img" aria-label="${esc(e.label+' '+number(v,e.unit))}"><circle cx="50" cy="50" r="35" fill="none" stroke="var(--line)" stroke-width="8"/>${v==null?'<path d="M36 50H64" stroke="var(--muted)" stroke-width="2"/>':`<circle cx="50" cy="50" r="35" pathLength="100" fill="none" stroke="var(--src-1)" stroke-width="8" stroke-dasharray="${v} ${100-v}" transform="rotate(-90 50 50)"/><text x="50" y="55" text-anchor="middle" fill="var(--ink)" font-size="18">${number(v,'%')}</text>`}</svg><span class="source">${glyph(e.cls)} ${esc(e.source)}</span><small>${e.value==null?'No value':'Retrieval '+esc(e.raw.provenance?.freshness?.status??'unknown')}</small></button>`}).join('')}</div>${row(fieldEntry('total_cloud_geometric','Geometric total cloud'))}<p class="hint">Rings are fraction gauges, not bearings or sky sectors. Layer fractions do not locate clouds, must not be added together, and do not establish seeing or transparency.</p></section>`;
}
const start=Date.parse(times[0]),end=Date.parse(times.at(-1)),percent=t=>100*(Date.parse(t)-start)/(end-start);
function windows(){const a=astro(),ok=validAstro();
 store('windows',entry('windows','Darkness and geometric windows',null,'',a.provenance?.source_id??'Astronomy',ok?'derived_here':'absent','Server intervals; geometry only, with no site-horizon or weather correction.',{twilight_bands:a.twilight_bands,moon:a.moon,milky_way_core:a.milky_way_core,provenance:a.provenance},response('astronomy')));
 const bands=[['Darkness',(a.twilight_bands??[]).filter(b=>b.kind==='night'),''],['Moon above horizon',a.moon?.above_horizon??[],'moon'],['Core window',a.milky_way_core?.windows??[],'core']];
 const blocks=b=>b.filter(v=>Date.parse(v.end)>start&&Date.parse(v.start)<end);
 return `<section class="panel">${header('Night geometry / 24 hours','04–05 September · UTC')}<div class="darkness">${bands.map(([label,bb,style])=>`<div class="night-row"><span>${label}</span><div class="night-band">${ok?blocks(bb).map(b=>`<span class="interval ${style}" style="left:${Math.max(0,percent(b.start))}%;width:${Math.min(100,percent(b.end))-Math.max(0,percent(b.start))}%" title="${esc(stamp(b.start)+' to '+stamp(b.end))}"></span>`).join(''):''}<span class="instant-line" style="left:${percent(state.instant)}%"></span></div></div>`).join('')}</div><div class="ticks"><span>00Z</span><span>06Z</span><span>12Z</span><span>18Z</span><span>00Z</span></div><div class="window-list">${bands.map(([label,bb])=>`<div class="window-item"><b>${label}</b>${ok?(blocks(bb).map(b=>`<time>${esc(stamp(b.start))} → ${esc(stamp(b.end))}</time>`).join('')||'<small>No interval in this displayed window</small>'):'<small>Unavailable, not an empty interval</small>'}</div>`).join('')}</div><p class="hint">${esc(a.milky_way_core?.caption??'Geometry unavailable. No darkness or moon value is substituted.')}</p><button data-inspect="windows">${glyph(ok?'derived_here':'absent')} ${esc(a.provenance?.source_id??'Astronomy unavailable')} · inspect intervals</button></section>`;
}
function kpSeries(key,label){
 const s=space()[key],all=(s?.readings??[]).filter(r=>r.value!=null),shown=all.filter(r=>Date.parse(r.time)>=start&&Date.parse(r.time)<=end),cls='unrecognised';
 store(key,entry(key,label,null,'',s?.source_id??'No source',cls,'Planetary index; evidence_class not supplied by this endpoint.',s??{value:null,reason:'Feed absent',notices:space().notices},response('space-weather')));
 const y=v=>102-v*9;
 return `<section class="panel">${header(label,`${esc(s?.source_id??'No source')} · ${esc(s?.freshness?.status??'unavailable')}`)}<svg class="plot" viewBox="0 0 700 140" role="img" aria-label="${esc(label)} at returned timestamps within 04–05 September; ${shown.length} points. Observed circle, estimated square, predicted triangle.">${[0,3,6,9].map(v=>`<line x1="30" y1="${y(v)}" x2="675" y2="${y(v)}" stroke="var(--line)"/><text x="20" y="${y(v)+4}" text-anchor="end">${v}</text>`).join('')}${shown.map(r=>{const x=30+percent(r.time)*6.45;return `<g fill="var(--src-1)"><title>${esc(stamp(r.time)+' '+r.value+' '+(r.status??'observed series'))}</title>${r.status==='predicted'?`<path d="M${x} ${y(r.value)-5}l5 9h-10z"/>`:r.status==='estimated'?`<rect x="${x-4}" y="${y(r.value)-4}" width="8" height="8"/>`:`<circle cx="${x}" cy="${y(r.value)}" r="4"/>`}</g>`}).join('')}<line x1="${30+percent(state.instant)*6.45}" x2="${30+percent(state.instant)*6.45}" y1="18" y2="108" stroke="var(--now)"/><text x="30" y="133">04 Sep 00Z</text><text x="675" y="133" text-anchor="end">05 Sep 00Z</text>${shown.length?'':'<text x="350" y="55" text-anchor="middle">No readings in the displayed window</text>'}</svg><p><span class="source">${glyph(cls)} Class not supplied</span> <span class="chip">${esc(s?.freshness?.status??'unavailable')}</span></p><small>● observed · ■ estimated · ▲ predicted. Status is the provider’s; points are not connected. Planetary context, not local aurora likelihood.</small><details><summary>${shown.length} displayed readings / full series in inspector</summary><table><thead><tr><th>UTC</th><th>Kp</th><th>Status</th></tr></thead><tbody>${shown.map(r=>`<tr><td>${esc(stamp(r.time))}</td><td>${r.value}</td><td>${esc(r.status??'observed series')}</td></tr>`).join('')}</tbody></table></details><button data-inspect="${key}">Inspect ${esc(label)} and all returned readings</button></section>`;
}
function solar(){const s=space().solar_wind;return `<section class="panel">${header('Solar wind / latest returned sample','Global context')}${['bz_gsm_nt','bt_nt'].map((k,i)=>row(entry('solar:'+k,i?'Bt magnitude':'Bz · GSM',s?.available?s[k]:null,'nT',s?.source_id??'SWPC','unrecognised',`Measured ${stamp(s?.measured_at)} · ${s?.freshness?.status??'unavailable'} · not the Focus instant`,{...s,field:k,evidence_class:null},response('space-weather')))).join('')}${row(absence('wind_speed','Solar wind speed','No speed or density series in this response'))}<p class="hint">Only a magnetic-field sample is served here. Its measured time stays explicit; changing the Focus does not move this sample through time.</p></section>`}
function missing(){return `<section class="panel">${header('Sky conditions','Absence stays visible')}${[fieldEntry('aurora_probability','Aurora probability at point'),absence('seeing','Seeing class','No admitted class returned; cloud fraction is not a seeing proxy'),absence('transparency','Transparency class','No admitted class returned; humidity is not substituted'),absence('hp30','Hp30','No series supplied by /space-weather'),absence('dst','Dst','No series supplied by /space-weather')].map(row).join('')}</section>`}
function camera(){const c=registry.camera.record;store('camera',entry('camera','Sky camera',null,'',c.operator,'absent','Partnership-only; position and camera orientation absent; no frame retrieved.',registry.camera,null));return `<section class="panel">${header('Sky camera','Registry context')}<div class="camera-placeholder"><div><h3>No eligible sky frame</h3><p>${esc(c.name)} · ${esc(c.status)}</p><small>Position, bearing and field of view unregistered</small></div></div><p class="muted">This camera is not associated with the Focus. A named sky camera does not establish sky-dome coverage or an alignment to this horizon.</p><button data-inspect="camera">${glyph('absent')} Inspect camera eligibility</button></section>`}
function renderInspector(){
 const e=records.get(state.selection);$('#inspector').hidden=!e;if(!e)return;
 $('#inspect-title').textContent=e.label;$('#inspect-sentence').textContent=e.value==null?`${e.source}: ${e.detail}`:`${e.source} supplies ${number(e.value,e.unit)}. ${e.detail}.`;
 const p=e.raw?.provenance??{},f={Source:e.source,'Evidence class':e.cls==='unrecognised'?'Not supplied / not classified':e.cls,'Requested Focus':state.instant,'Evidence valid time':p.valid_time??e.raw?.valid_time??e.raw?.measured_at??'See raw intervals or readings','Run time':p.run_time??'Not supplied','Run stale':p.run_stale==null?'Unknown · '+(p.run_stale_reason??'Not supplied'):String(p.run_stale),'Retrieval time':p.retrieval_time??'Not supplied','Freshness at response':p.freshness?.status??e.raw?.freshness?.status??'Not supplied','Quality':p.quality?.status??'Not supplied','Sampling':p.sample_method??'Not supplied','Sample distance':p.sample_distance_km==null?'Not supplied':p.sample_distance_km+' km','Method':p.derivation??'Not supplied','Citation':p.derivation_citation??'Not supplied','Comparability':e.raw?.comparability??'Not supplied','Terms / attribution':p.attribution??p.licence??'See raw record / not supplied','Capture time':e.request?.captured_at??'Registry context / UI state','Request':e.request?.request_url??'Repository registry / absent capability'};
 $('#inspect-fields').innerHTML=Object.entries(f).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('');$('#inspect-raw').textContent=JSON.stringify({selected:e.raw,capture:e.request,prototype:true},null,2);
}
function visibleFocusTarget(node){return node?.isConnected&&!node.disabled&&node.getClientRects().length>0&&!node.closest('[hidden]')}
function matchingInspect(key){return [...document.querySelectorAll('[data-inspect]')].find(node=>node.dataset.inspect===key&&visibleFocusTarget(node))}
function closeInspector(){
 const opener=visibleFocusTarget(inspectorOpener?.node)?inspectorOpener.node:matchingInspect(inspectorOpener?.key);
 state.selection=null;renderInspector();(opener??$('#heading')).focus();inspectorOpener=null;
}
function render(){
 const focused=document.activeElement,focusedKey=focused?.dataset?.inspect;

 for(const[k,v]of Object.entries(cssVars(T,'C',state.theme)))document.documentElement.style.setProperty(k,v);document.documentElement.style.colorScheme=state.theme==='light'?'light':'dark';document.body.dataset.cv=state.cv;records.clear();
 for(const id of ['focus','theme','mode'])$('#'+id).value=state[id];$('#instant').value=state.instant;
 $('#heading').textContent='Sky / '+names[state.variant];$('#hypothesis').textContent={A:'Start with orientation; keep weather fractions beside the horizon.',B:'Start with the night; align geometry and planetary context in time.',C:'Start with what is known; keep source, limits and missing capabilities in view.'}[state.variant];
 $('#focus-meta').textContent=`${position().latitude}, ${position().longitude} · ${state.focus==='site'?'registered horizon, unsurveyed':'no_site · horizon unknown'}`;
 const rr=['astronomy','point','space-weather'].map(r=>`${r}: ${response(r).response?.data_mode??'failed'}`).join(' · ');
 $('#notice').textContent=state.mode==='capture'?`SAVED API CAPTURE · ${capture.captured_at} · ${rr}. Historical responses, not current conditions; separate requests, not one atomic revision.`:state.mode==='outage'?'UNAVAILABLE STATE STUDY · deliberately empty numeric data. Site and camera registry context remains available.':`${pending?'READING LIVE API':'LIVE API RESPONSE'} · ${rr}. Response freshness is shown per source; operational: false.`;
 const stage=$('#stage');stage.className='stage '+state.variant;
 if(state.variant==='A')stage.innerHTML=`<div>${horizon()}${clouds()}${windows()}</div><div>${geometry()}${missing()}${solar()}${camera()}${kpSeries('kp_forecast','Kp outlook')}${kpSeries('kp_observed','Kp observed')}</div>`;
 if(state.variant==='B')stage.innerHTML=`${windows()}<div class="wide-grid"><div>${kpSeries('kp_observed','Kp observed')}${kpSeries('kp_forecast','Kp outlook')}${solar()}</div><div>${geometry()}${clouds()}${missing()}</div></div><div class="wide-grid">${horizon()}${camera()}</div>`;
 if(state.variant==='C')stage.innerHTML=`<nav class="category-nav" aria-label="Sky evidence categories"><a href="#celestial">01 / Celestial<small>Altitudes and windows</small></a><a href="#atmosphere">02 / Atmosphere<small>Fractions and absences</small></a><a href="#planetary">03 / Planetary<small>Indices and solar wind</small></a><a href="#site-context">04 / Site context<small>Horizon and camera</small></a></nav><div class="panel"><section id="celestial" class="ledger-lane"><header><div class="eyebrow">01 / Computed here</div><h2>Celestial</h2></header><div>${geometry()}${windows()}</div></section><section id="atmosphere" class="ledger-lane"><header><div class="eyebrow">02 / Point evidence</div><h2>Atmosphere</h2></header><div>${clouds()}${missing()}</div></section><section id="planetary" class="ledger-lane"><header><div class="eyebrow">03 / No local claim</div><h2>Planetary</h2></header><div>${kpSeries('kp_observed','Kp observed')}${kpSeries('kp_forecast','Kp outlook')}${solar()}</div></section><section id="site-context" class="ledger-lane"><header><div class="eyebrow">04 / Registry</div><h2>Site context</h2></header><div>${horizon()}${camera()}</div></section></div>`;
 const tl=capture.requests.find(r=>r.request_url.endsWith('/timeline'))?.response;$('#tier').textContent=(tl?.items.find(i=>i.valid_time_utc===state.instant)?.tier??'unknown')+' tier at saved capture';$('#local-time').textContent=new Date(state.instant).toLocaleString('en-CA',{timeZone:'America/St_Johns'})+' · America/St_Johns';
 $('#time-track').innerHTML=times.map(t=>`<span class="sample-mark ${t===state.instant?'active':''}" style="left:${percent(t)}%" title="${t}"></span>`).join('');$('#variant-label').textContent=state.variant+' · '+names[state.variant];$('#refresh').disabled=pending;
 $('#state').textContent=JSON.stringify({...state,coordinates:position(),tokens:'C Hyperlegible / provider slots / red night',operational:false,requests:['astronomy','point','space-weather'].map(r=>({route:r,url:response(r).request_url,captured_at:response(r).captured_at,status:response(r).status,error:response(r).error}))},null,2);
 for(const k of ['variant','focus','instant','theme'])q.set(k,state[k]);history.replaceState(null,'','?'+q);renderInspector();
 if(!focused?.isConnected&&focusedKey)(matchingInspect(focusedKey)??$('#heading')).focus();
}
async function readLive(){const seq=++sequence;state.mode='live';pending=true;live={};render();const base='/api/experiments/weather/v0/',params=new URLSearchParams({...position(),valid_time:state.instant});const responses=await Promise.all(['astronomy','point','space-weather'].map(async route=>{const url=base+route+(route==='space-weather'?'':'?'+params),requested_at=new Date().toISOString();try{const r=await fetch(url,{signal:AbortSignal.timeout(20000)});if(!r.headers.get('content-type')?.includes('application/json'))throw Error('API request failed (HTTP '+r.status+')');const raw=await r.json();return [route,{request_url:url,requested_at,captured_at:new Date().toISOString(),status:r.status,response:r.ok?raw:{data_mode:'unavailable',notices:['HTTP '+r.status],raw}}]}catch(e){return[route,{request_url:url,requested_at,error:e.message,response:{data_mode:'unavailable',notices:[e.message]}}]}}));if(seq!==sequence)return;live=Object.fromEntries(responses);pending=false;render()}
$('#instant').innerHTML=times.map(t=>`<option value="${t}">${stamp(t)}</option>`).join('');
for(const id of ['focus','instant'])$('#'+id).onchange=e=>{state[id]=e.target.value;if(state.mode==='live')readLive();else render()};
$('#theme').onchange=e=>{state.theme=e.target.value;render()};$('#vision').onchange=e=>{state.cv=e.target.value;render()};
$('#mode').onchange=e=>{state.mode=e.target.value;if(state.mode==='live')readLive();else{sequence++;pending=false;render()}};$('#refresh').onclick=readLive;
function cycle(d){state.variant=['A','B','C'][(['A','B','C'].indexOf(state.variant)+d+3)%3];render()}
$('#previous').onclick=()=>cycle(-1);$('#next').onclick=()=>cycle(1);
// Variant navigation uses its native Previous/Next buttons; arrow keys belong to controls and scrolling.
$('#inspector').addEventListener('keydown',e=>{if(e.key==='Escape'&&!e.defaultPrevented){e.preventDefault();e.stopPropagation();closeInspector()}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-inspect]');if(b){inspectorOpener={node:b,key:b.dataset.inspect};state.selection=b.dataset.inspect;renderInspector();$('#inspect-title').focus();$('#state').textContent=JSON.stringify({...JSON.parse($('#state').textContent),...state},null,2)}});
$('#close-inspector').onclick=closeInspector;render();
